/* BUILD103: baked safe paths, stable logical residents, bounded pooled rendering. */
async function createCampusLife103(B,scene,world,nav,plan,player,shuttle,leisure,hooks){
 const raw=await fetch('data/campus-life103.json').then(r=>r.json()),spots=raw.spots,coats=['cheese','tuxedo','calico','tabby','black','cream'],roles=['commuter','reader','artist','musician','athlete','relax'],dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
 const residents=raw.residents.map((n,i)=>({...n,coat:coats[i%6],role:roles[i%6],phase:(i*.6180339)%1,speed:.65+(i%7)*.07,rest:6+i%8,position:{...n.path.pts[0]},heading:0,action:'idle',seated:false,model:null,lastAnim:0}));
 for(const n of residents){n.path.cumulative=[0];for(let i=1;i<n.path.pts.length;i++){const a=n.path.pts[i-1],b=n.path.pts[i];n.path.cumulative.push(n.path.cumulative.at(-1)+Math.hypot(b.x-a.x,b.z-a.z));}n.path.len=n.path.cumulative.at(-1);}
 const groups=[...new Set(residents.map(n=>n.zone))].map(name=>[name]);
 // Allocate only the visible budget, not 180 models. The asset owns shared geometry/materials.
 const {createCatNPC}=await import('./assets/cat-npc103.js');const pool=[],active=new Map(),budget=24,detailed=10;
 for(let i=0;i<budget;i++){const model=createCatNPC(B,scene,{id:'cat-pool-'+i,coat:coats[i%6],role:roles[i%6]});model.renderMeshes.forEach(m=>{m.isPickable=false;m.checkCollisions=false;m.metadata={...m.metadata,renderRole99:'actor',npcVisual103:true}});model.setEnabled(false);pool.push(model);if(i%4===3)await new Promise(r=>setTimeout(r,0));}
 // Existing Abang bench has two independent free seat anchors. Player interaction spots are elsewhere.
 const bench=nav.plazas72?.benches?.[0];if(bench){let seats=residents.filter(n=>n.zone==='인문대·자하연').slice(0,2);seats.forEach((n,i)=>{n.restSeat={x:bench.x+(i? .7:-.7),y:world.floorAt(bench.x,bench.z)+.52,z:bench.z};n.role=i?'relax':'reader';n.coat=i?'cream':'tuxedo';})}
 let lastLogic=-1,lastSelect=-1,enabled=true,tick=0,frustum=[];const started=performance.now();
 function logical(n,t){const still=n.social||n.waitPoint;if(still&&!n.restSeat){n.position={x:still.x,y:still.y,z:still.z};n.heading=still.heading;n.action=n.social?'nod':'idle';n.seated=false;return}if(n.restSeat){n.position={...n.restSeat};n.heading=Math.PI;n.action=n.role==='reader'?'read':'drink';n.seated=true;return}const path=n.path,travel=path.len/n.speed,cycle=travel*2+n.rest*2,u=(t+n.phase*cycle)%cycle;let d,reverse=false;if(u<travel){d=u*n.speed;n.action='walk'}else if(u<travel+n.rest){d=path.len;n.action=['idle','read','sketch','nod','stretch','drink'][roles.indexOf(n.role)]}else if(u<travel*2+n.rest){d=path.len-(u-travel-n.rest)*n.speed;reverse=true;n.action='walk'}else{d=0;n.action=['idle','read','sketch','nod','stretch','drink'][roles.indexOf(n.role)]}let lo=0,hi=path.pts.length-2;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(path.cumulative[mid]<=d)lo=mid;else hi=mid-1;}const i=lo,a=path.pts[i],b=path.pts[i+1],v=Math.min(1,(d-path.cumulative[i])/(path.cumulative[i+1]-path.cumulative[i]||1));n.position={x:a.x+(b.x-a.x)*v,y:a.y+(b.y-a.y)*v,z:a.z+(b.z-a.z)*v};if(Math.hypot(b.x-a.x,b.z-a.z)<.02&&Math.abs(b.y-a.y)>.02)n.position.y=world.floorAt(n.position.x,n.position.z,n.position.y);n.heading=Math.atan2(b.x-a.x,b.z-a.z)+(reverse?Math.PI:0);n.seated=false;}
 function release(n){if(!n.model)return;n.model.setEnabled(false);pool.push(n.model);n.model=null;active.delete(n.id)}
 function update(now,dt){if(!enabled)return;const time=(now-started)/1000;
  if(now-lastLogic>500){lastLogic=now;for(const n of residents)if(!n.model)logical(n,time);tick++;}
  if(now-lastSelect>500){lastSelect=now;frustum=B.Frustum.GetPlanes(scene.getTransformMatrix());const range=Math.min(150,[60,110,180,450,6000][hooks.range()-1]),keep=range+25;for(const n of active.values())if(dist(n.position,player.position)>keep)release(n);const candidates=residents.filter(n=>!n.model&&dist(n.position,player.position)<range).sort((a,b)=>dist(a.position,player.position)-dist(b.position,player.position));for(const n of candidates){if(active.size>=budget)break;const match=pool.findIndex(m=>m.coat===n.coat&&m.role===n.role),m=pool.splice(match<0?pool.length-1:match,1)[0];n.model=m;n.modelAction=null;n.modelSeated=null;if(m.coat===n.coat&&m.role===n.role)m.setAction(n.action,{seated:n.seated});else m.reset({coat:n.coat,role:n.role,phase:n.phase*6,action:n.action});m.renderMeshes.forEach(mesh=>{mesh.isPickable=false;mesh.checkCollisions=false;mesh.metadata={...mesh.metadata,renderRole99:'actor',npcVisual103:true}});m.root.position.copyFromFloats(n.position.x,n.position.y,n.position.z);m.root.rotation.y=n.heading;m.update(0,time);m.setEnabled(true);active.set(n.id,n);}}
  const near=[...active.values()].sort((a,b)=>dist(a.position,player.position)-dist(b.position,player.position));for(let i=0;i<near.length;i++){const n=near[i],prior=n.position;logical(n,time-(n.delay||0));if(n.action==='walk'&&near.some(q=>q!==n&&dist(q.position,n.position)<.8)){n.position=prior;n.delay=(n.delay||0)+dt;n.action='idle';}const m=n.model;m.root.position.copyFromFloats(n.position.x,n.position.y,n.position.z);m.root.rotation.y=n.heading;const inView=!frustum.length||frustum.every(p=>p.dotCoordinate(new B.Vector3(n.position.x,n.position.y+.8,n.position.z))> -1),rate=!inView?800:i<detailed?0:150;if(now-n.lastAnim>=rate||n.modelAction!==n.action){n.lastAnim=now;if(n.modelAction!==n.action||n.modelSeated!==n.seated){m.setAction(n.action,{seated:n.seated});n.modelAction=n.action;n.modelSeated=n.seated}m.update(dt,time);}if(n.restSeat){m.root.computeWorldMatrix(true);m.anchors.seat.computeWorldMatrix(true);const at=m.anchors.seat.getAbsolutePosition();m.root.position.addInPlace(new B.Vector3(n.restSeat.x-at.x,n.restSeat.y-at.y,n.restSeat.z-at.z));}else if(n.action==='idle'){const other=near.find(q=>q!==n&&q.action!=='walk'&&dist(q.position,n.position)>1&&dist(q.position,n.position)<3.5);if(other)m.root.rotation.y=Math.atan2(other.position.x-n.position.x,other.position.z-n.position.z);}}

 }
 return{spots,residents,pool,update,setEnabled(v){enabled=v;if(!v)for(const n of [...active.values()])release(n)},audit:()=>({total:residents.length,active:active.size,budget,detailed,logicalTicks:tick,groups:groups.map(g=>({name:g[0],count:residents.filter(n=>n.zone===g[0]).length})),shown:[...active.values()].map(n=>({id:n.id,coat:n.coat,role:n.role,action:n.action,position:n.position}))})};
}
